package net.guzhenren.daotu;public class DaotuDrawTable{public static final String TALENT_PREFIX="talent:";public record Candidate(String key,String label,double amount,boolean percent){public boolean isTalent(){return key.startsWith(TALENT_PREFIX);}public String talentId(){return isTalent()?key.substring(TALENT_PREFIX.length()):null;}}public static double zhuanScale(double d){return 1;}public static java.util.List<Candidate> candidates(net.minecraft.world.entity.player.Player p,int i,net.minecraft.util.RandomSource r){return java.util.List.of(new Candidate("attack_damage","力量",0.03,true));}}